$changed = @(); $failed = @()
foreach ($f in $files) {
  $rel = $f[0]; $want = $f[1]
  $dest = Join-Path $root ($rel -replace '/', '\')
  if ((Test-Path $dest) -and ((Get-FileHash $dest -Algorithm SHA256).Hash.ToLower() -eq $want)) { continue }
  $tmp = "$dest.vdl"
  try {
    New-Item -ItemType Directory -Force -Path (Split-Path $dest) | Out-Null
    Invoke-WebRequest -UseBasicParsing "https://raw.githubusercontent.com/addu864/vanta/$commit/$rel" -OutFile $tmp
    if ((Get-FileHash $tmp -Algorithm SHA256).Hash.ToLower() -ne $want) { throw "hash mismatch" }
    Move-Item -Force $tmp $dest; $changed += $rel
  } catch { $failed += "$rel : $_"; Remove-Item $tmp -ErrorAction SilentlyContinue }
}
"updated: $($changed.Count)"; $changed; "failed: $($failed.Count)"; $failed
# Ping the popular servers with Vanta's own code (bundled Python) to confirm live status from this PC.
$py = Join-Path $root 'python.exe'
if (Test-Path $py) {
  Push-Location $root
  & $py -c "import sys; sys.path.insert(0,'.'); from vanta.launcher.servers import popular as p; [print(r['name'], r['address'], r['status'].get('online'), r['status'].get('players'), r['status'].get('error','')) for r in p.statuses(p.DEFAULT_SERVERS)]"
  Pop-Location
}

Stop-Transcript | Out-Null
